CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL, starts TEXT NOT NULL, ends TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'attendee' CHECK(role IN ('attendee','organizer')));
CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower ON users(lower(email));
CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id), category TEXT NOT NULL CHECK(category IN ('general','vip','speaker')), company TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', interests TEXT NOT NULL DEFAULT '', preferences TEXT NOT NULL DEFAULT '', consent INTEGER NOT NULL CHECK(consent=1), reference TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS auth_sessions(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_user ON auth_sessions(user_id);
CREATE TABLE IF NOT EXISTS invitations(code_hash TEXT PRIMARY KEY, category TEXT NOT NULL CHECK(category IN ('vip','speaker')));
CREATE TABLE IF NOT EXISTS speakers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, title TEXT NOT NULL, company TEXT NOT NULL, bio TEXT NOT NULL, initials TEXT NOT NULL, color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY, event_id INTEGER NOT NULL REFERENCES events(id), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL, outcomes TEXT NOT NULL, track TEXT NOT NULL, tags TEXT NOT NULL, start TEXT NOT NULL, "end" TEXT NOT NULL CHECK("end">start), room TEXT NOT NULL, format TEXT NOT NULL, level TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>=0), access TEXT NOT NULL DEFAULT 'all' CHECK(access IN ('all','vip')));
CREATE INDEX IF NOT EXISTS session_time ON sessions(start,"end");
CREATE TABLE IF NOT EXISTS session_speakers(session_id INTEGER NOT NULL REFERENCES sessions(id), speaker_id INTEGER NOT NULL REFERENCES speakers(id), PRIMARY KEY(session_id,speaker_id));
CREATE TABLE IF NOT EXISTS reservations(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), session_id INTEGER NOT NULL REFERENCES sessions(id), created TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), UNIQUE(user_id,session_id));
CREATE INDEX IF NOT EXISTS reservation_session ON reservations(session_id);
CREATE TABLE IF NOT EXISTS waitlist(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), session_id INTEGER NOT NULL REFERENCES sessions(id), UNIQUE(user_id,session_id));
CREATE INDEX IF NOT EXISTS waitlist_session ON waitlist(session_id,id);
CREATE TABLE IF NOT EXISTS passes(user_id TEXT PRIMARY KEY REFERENCES users(id), token TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS checkins(user_id TEXT PRIMARY KEY REFERENCES users(id), organizer_id TEXT NOT NULL REFERENCES users(id), checked_at TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE TABLE IF NOT EXISTS transitions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), session_id INTEGER NOT NULL REFERENCES sessions(id), kind TEXT NOT NULL, created TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
CREATE OR REPLACE FUNCTION convene_reservation_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(119015,2027);
  IF (SELECT count(*) FROM reservations WHERE session_id=NEW.session_id)>=(SELECT capacity FROM sessions WHERE id=NEW.session_id) THEN RAISE EXCEPTION 'Session is full'; END IF;
  IF (SELECT access FROM sessions WHERE id=NEW.session_id)='vip' AND (SELECT category FROM profiles WHERE user_id=NEW.user_id)<>'vip' THEN RAISE EXCEPTION 'VIP access required'; END IF;
  IF EXISTS(SELECT 1 FROM reservations r JOIN sessions existing ON existing.id=r.session_id JOIN sessions candidate ON candidate.id=NEW.session_id WHERE r.user_id=NEW.user_id AND existing.start<candidate."end" AND candidate.start<existing."end") THEN RAISE EXCEPTION 'Session overlaps with an existing reservation'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER prevent_overbooking BEFORE INSERT ON reservations FOR EACH ROW EXECUTE FUNCTION convene_reservation_guard();
CREATE OR REPLACE FUNCTION convene_capacity_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(119015,2027);
  IF NEW.capacity<(SELECT count(*) FROM reservations WHERE session_id=NEW.id) THEN RAISE EXCEPTION 'Capacity cannot be below confirmed reservations'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER prevent_capacity_reduction BEFORE UPDATE OF capacity ON sessions FOR EACH ROW EXECUTE FUNCTION convene_capacity_guard();
INSERT INTO migrations VALUES(1) ON CONFLICT DO NOTHING;
